 private static string $root;
 public static function setUpBeforeClass():void{self::$root=sys_get_temp_dir().'/forms-fresh-source-'.bin2hex(random_bytes(8));mkdir(self::$root.'/lib/Mcp',0700,true);$s=file_get_contents(__DIR__.'/../src/SourceIdentity.php');file_put_contents(self::$root.'/lib/Mcp/SourceIdentity.php',$s);$map=['lib/Mcp/SourceIdentity.php'=>hash('sha256',$s)];for($i=0;$i<55;$i++){$p='file'.$i.'.php';file_put_contents(self::$root.'/'.$p,'<?php return 1;');$map[$p]=hash_file('sha256',self::$root.'/'.$p);}file_put_contents(self::$root.'/mcp-guard-installed.json',json_encode(['protocol'=>1,'formsVersion'=>'5.4.2','sha256'=>$map]));require self::$root.'/lib/Mcp/SourceIdentity.php';}
 public static function tearDownAfterClass():void{$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator(self::$root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as$f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir(self::$root);}
