 protected function setUp():void{$this->set('businessFrame',new stdClass());$this->set('frameBulkControl',null);$this->set('fileBoundary',null);$this->set('current',['origin'=>['signed'=>true],'verified'=>['tool'=>'forms_transfer','references'=>['form_id'=>1]],'action'=>'forms_transfer','input'=>['id'=>1,'owner_id'=>'target'],'file_action'=>'forms_transfer','file_impact'=>['share_impact'=>['type'=>7]]]);\OCP\Server::$fence=new \OCA\Forms\Mcp\Service\FormsRevisionFence();\OCP\Server::$authorization=new class {public int $calls=0;public array $frames=[];public bool $revoked=false;public ?Closure $during=null;public function assert(array $origin):void{$this->check();}public function assertFiles(array $origin,string $action,array $manifest):void{$this->check();}public function assertTransferFiles(array $origin,?array $control,array $manifest,array $copies,array $parents,Closure $resolve):void{$this->check();$resolve();}private function check():void{++$this->calls;$this->frames[]=(new ReflectionProperty(SourceIdentity::class,'verifiedReadFrame'))->getValue()!==null;if($this->during!==null)($this->during)();if($this->revoked||!SourceIdentity::verify()||!SourceIdentity::verify())throw new RuntimeException('denied');}};}
 protected function tearDown():void{file_put_contents(self::$root.'/file0.php','<?php return 1;');$this->set('current',null);$this->set('businessFrame',null);$this->set('fileBoundary',null);self::assertNull((new ReflectionProperty(SourceIdentity::class,'verifiedReadFrame'))->getValue());}
 private function finalAuthority():Closure{$a=OriginContext::transferFilesAuthority();\OCP\Server::$authorization->calls=0;\OCP\Server::$authorization->frames=[];return$a;}
 public function testFinalTransferReadKeepsCallbackOutsideAndChecksCurrentNativeAuthority():void{$outside=false;$resolved=false;OriginContext::withFileBoundary(static function()use(&$outside):void{$outside=(new ReflectionProperty(SourceIdentity::class,'verifiedReadFrame'))->getValue()===null;},function()use(&$resolved):void{$a=$this->finalAuthority();\OCA\Forms\Mcp\Service\TransferFinalFiles::admitted($a,static function()use(&$resolved):void{$resolved=SourceIdentity::verifiedReadActive();});});self::assertTrue($outside);self::assertTrue($resolved);self::assertSame([true],\OCP\Server::$authorization->frames);}
 public function testFinalTransferReadRechecksCodeAfterResolver():void{$a=$this->finalAuthority();$this->expectException(RuntimeException::class);\OCA\Forms\Mcp\Service\TransferFinalFiles::admitted($a,static fn()=>file_put_contents(self::$root.'/file0.php','<?php return 2;'));}
 public function testFinalTransferReadRejectsFenceEndingDuringResolver():void{$a=$this->finalAuthority();$this->expectException(RuntimeException::class);\OCA\Forms\Mcp\Service\TransferFinalFiles::admitted($a,static function():void{\OCP\Server::$fence->live=false;});}
 public function testFinalTransferReadCannotReusePermissionsAfterExternalRevocation():void{$this->expectException(RuntimeException::class);OriginContext::withFileBoundary(static function():void{\OCP\Server::$authorization->revoked=true;},function():void{$a=$this->finalAuthority();\OCA\Forms\Mcp\Service\TransferFinalFiles::admitted($a,static fn()=>null);});}
 public function testFinalTransferReadDoesNotBatchArbitraryResolver():void{$a=$this->finalAuthority();$inside=true;$a(['files'=>[]],[],[],static function()use(&$inside):void{$inside=(new ReflectionProperty(SourceIdentity::class,'verifiedReadFrame'))->getValue()!==null;});self::assertFalse($inside);self::assertSame([false],\OCP\Server::$authorization->frames);}
 public function testEveryFreshAuthorizationStillRunsAndRevocationIsImmediate():void{OriginContext::assertFiles('forms_transfer',[]);self::assertSame([true],\OCP\Server::$authorization->frames);\OCP\Server::$authorization->revoked=true;$this->expectException(RuntimeException::class);try{OriginContext::assertFiles('forms_transfer',[]);}finally{self::assertSame(2,\OCP\Server::$authorization->calls);}}
 public function testCodeMutationDuringAuthorizationIsRejected():void{\OCP\Server::$authorization->during=static fn()=>file_put_contents(self::$root.'/file0.php','<?php return 2;');$this->expectException(RuntimeException::class);OriginContext::assertFiles('forms_transfer',[]);}
 public function testExternalCallbackRunsOutsideSourceFrameBeforeBuiltInFreshAuthorization():void{$outside=false;OriginContext::withFileBoundary(static function()use(&$outside):void{$outside=(new ReflectionProperty(SourceIdentity::class,'verifiedReadFrame'))->getValue()===null;},static fn()=>OriginContext::assertFiles('forms_transfer',[]));self::assertTrue($outside);self::assertSame([true],\OCP\Server::$authorization->frames);}
 public function testCodeMutationInExternalCallbackIsRejectedBeforeBuiltInAuthorization():void{$this->expectException(RuntimeException::class);try{OriginContext::withFileBoundary(static fn()=>file_put_contents(self::$root.'/file0.php','<?php return 2;'),static fn()=>OriginContext::assertFiles('forms_transfer',[]));}finally{self::assertSame(0,\OCP\Server::$authorization->calls);}}
 public function testBusinessFrameChangeDuringAuthorizationIsRejected():void{\OCP\Server::$authorization->during=fn()=> $this->set('businessFrame',new stdClass());$this->expectException(RuntimeException::class);OriginContext::assertFiles('forms_transfer',[]);}
 public function testNonCirclePathKeepsOriginalAuthorizationFlow():void{$c=(new ReflectionProperty(OriginContext::class,'current'))->getValue();$c['file_impact']['share_impact']['type']=1;$this->set('current',$c);OriginContext::assertFiles('forms_transfer',[]);self::assertSame([false],\OCP\Server::$authorization->frames);}
 public function testExistingVerifiedReadFrameIsReusedAndNotClosedEarly():void{SourceIdentity::withinVerifiedReadFrame(static fn()=>null,static function():void{OriginContext::assertFiles('forms_transfer',[]);self::assertSame([true],\OCP\Server::$authorization->frames);self::assertNotNull((new ReflectionProperty(SourceIdentity::class,'verifiedReadFrame'))->getValue());});}
